// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
bool DbImportSink::exec( const std::string & sql )
{
    m_db.exec( sql );

    const std::string err = m_db.get_error();

    if( !err.empty() ) {
        m_error = err + " (sql: " + sql.substr( 0, 200 ) + ")";
        return false;
    }

    return true;
}
