// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
bool DbImportSink::insertRows( const std::vector<Measurement> & batch )
{
    std::string sql = "INSERT INTO " + m_table
        + " (measured_at, temp_inside, hum_inside, temp_outside, hum_outside) VALUES ";

    for( std::size_t i = 0; i < batch.size(); ++i ) {
        const Measurement & m = batch[ i ];

        if( i ) {
            sql += ",";
        }

        sql += "("
            + quote( m.measuredAt() ) + ","
            + num( m.temp_inside )  + ","
            + num( m.hum_inside )   + ","
            + num( m.temp_outside ) + ","
            + num( m.hum_outside )
            + ")";
    }

    return exec( sql );
}
