// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
bool DbImportSink::updateState( std::streamoff new_offset )
{
    const std::string size = Tools::format( "%lld", (long long)m_file_size );

    const std::string mtime = m_mtime.empty() ? "NULL" : quote( m_mtime );

    const std::string sql =
        "INSERT INTO " + m_state_table
        + " (name, byte_offset, file_size, mtime, updated_at) VALUES ("
        + quote( m_state_name ) + ","
        + Tools::format( "%lld", (long long)new_offset ) + ","
        + size + "," + mtime + ",NOW())"
        + " ON DUPLICATE KEY UPDATE byte_offset=VALUES(byte_offset),"
        + " file_size=VALUES(file_size), mtime=VALUES(mtime), updated_at=NOW()";

    return exec( sql );
}
