// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
bool DbImportSink::store( const std::vector<Measurement> & batch, std::streamoff new_offset )
{
    if( !exec( "BEGIN" ) ) {
        return false;
    }

    if( !batch.empty() && !insertRows( batch ) ) {
        m_db.rollback();
        return false;
    }

    if( !updateState( new_offset ) ) {
        m_db.rollback();
        return false;
    }

    return exec( "COMMIT" );
}
// End of AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0

// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
bool DbImportSink::loadOffset( std::streamoff & offset )
{
    offset = 0;

    const std::string sql = "SELECT byte_offset FROM " + m_state_table
        + " WHERE name=" + quote( m_state_name );

    auto erg = m_db.select( sql, false );

    if( !erg ) {
        // table may not exist yet - treat as first run
        const std::string err = m_db.get_error();
        if( !err.empty() && err.find( "doesn't exist" ) == std::string::npos
            && err.find( "does not exist" ) == std::string::npos ) {
            m_error = err;
            return false;
        }
        return true;
    }

    if( erg.row_list.values.empty() || erg.row_list.values[0].empty() ) {
        return true;    // no row yet
    }

    offset = (std::streamoff)std::atoll( erg.row_list.values[0][0].c_str() );
    return true;
}
