bool DbImportSink::createTables()
{
    if( !exec( "CREATE TABLE IF NOT EXISTS " + m_table + " ("
               " id           BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,"
               " measured_at  DATETIME        NOT NULL,"
               " temp_inside  DECIMAL(5,2)    NULL,"
               " hum_inside   DECIMAL(5,2)    NULL,"
               " temp_outside DECIMAL(5,2)    NULL,"
               " hum_outside  DECIMAL(5,2)    NULL,"
               " KEY idx_measured_at (measured_at)"
               ") ENGINE=InnoDB DEFAULT CHARSET=utf8mb4" ) ) {
        return false;
    }

    return exec( "CREATE TABLE IF NOT EXISTS " + m_state_table + " ("
                 " name        VARCHAR(64) NOT NULL PRIMARY KEY,"
                 " byte_offset BIGINT      NOT NULL,"
                 " file_size   BIGINT      NULL,"
                 " mtime       DATETIME    NULL,"
                 " updated_at  DATETIME    NOT NULL"
                 ") ENGINE=InnoDB DEFAULT CHARSET=utf8mb4" );
}
